INSERT INTO rpg.phb_creature_template_trait (template_slug, name, description, sort_order) VALUES
  ('aarakocra-aeromante', 'Sentidos', 'Percepção Passiva 17.', 0),
  ('aarakocra-escaramucador', 'Sentidos', 'Percepção Passiva 15.', 0),
  ('abolete', 'Sentidos', 'Visão no Escuro 36 m. Percepção Passiva 20.', 0),
  ('abolete', 'Amphibious', 'The aboleth can breathe air and water.', 1),
  ('abolete', 'Eldritch Restoration', 'If destroyed, the aboleth gains a new body in 5d10 days, reviving with all its Hit Points in the Far Realm or another location chosen by the DM.', 2),
  ('abolete', 'Legendary Resistance (3/Day, or 4/Day in Lair)', 'If the aboleth fails a saving throw, it can choose to succeed instead.', 3),
  ('abolete', 'Mucus Cloud', 'While underwater, the aboleth is surrounded by mucus. Constitution Saving Throw: DC 14, each creature in a 5-foot Emanation originating from the aboleth at the end of the aboleth’s turn. Failure: The target is cursed. Until the curse ends, the target’s skin becomes slimy, the target can breathe air and water, and it can’t regain Hit Points unless it is underwater.', 4),
  ('abolete', 'Probing Telepathy', 'If a creature the aboleth can see communicates telepathically with the aboleth, the aboleth learns the creature’s greatest desires.', 5),
  ('ankheg', 'Sentidos', 'Visão no Escuro 18 m, Sentido Sísmico 18 m. Percepção Passiva 11.', 0),
  ('ankheg', 'Tunneler', 'The ankheg can burrow through solid rock at half its Burrow Speed and leaves a 10-foot-diameter tunnel in its wake.', 1),
  ('arbusto-despertado', 'Sentidos', 'Percepção Passiva 10.', 0),
  ('arcanalote', 'Sentidos', 'Visão Verdadeira 36 m. Percepção Passiva 17.', 0),
  ('arcanalote', 'Fiendish Restoration', 'If the arcanaloth dies outside Gehenna, its body dissolves into ichor, and it gains a new body instantly and revives with all its Hit Points in Gehenna.', 1),
  ('arcanalote', 'Magic Resistance', 'The arcanaloth has Advantage on saving throws against spells and other magical effects.', 2),
  ('arcanalote', 'Soul Tome', 'The arcanaloth has a magic tome. While holding or carrying the tome, the arcanaloth can use its Banishing Claw action.', 3),
  ('armadura-animada', 'Sentidos', 'Visão às Cegas 18 m. Percepção Passiva 6.', 0),
  ('arquibruxa', 'Sentidos', 'Visão Verdadeira 18 m. Percepção Passiva 21.', 0),
  ('arquibruxa', 'Coven Magic', 'While within 30 feet of at least two hag allies, the hag can cast one of the following spells, requiring no Material components, using the spell’s normal casting time, and using Intelligence as the spellcasting ability (spell save DC 19): Augury, Find Familiar, Identify, Locate Object, Scrying, or Unseen Servant. The hag must finish a Long Rest before using this trait to cast that spell again.', 1),
  ('arquibruxa', 'Legendary Resistance (4/Day, or 5/Day in Lair)', 'If the hag fails a saving throw, it can choose to succeed instead.', 2),
  ('arquibruxa', 'Magic Resistance', 'The hag has Advantage on saving throws against spells and other magical effects.', 3),
  ('arquibruxa', 'Spiteful Escape', 'When the hag drops to 0 Hit Points, it dies only if it is within 30 feet of its anathema (a thing the DM chooses as the hag’s most hated thing). Otherwise, the hag drops to 1 Hit Point and teleports to a harmless demiplane, and it can’t return to the plane it left for 2d6 days. When the hag teleports away, each creature within 60 feet of the space it left is cursed. Until the curse ends, a creature has Disadvantage on ability checks and saving throws, and the hag knows its location anywhere in the multiverse.', 4),
  ('arvore-despertada', 'Sentidos', 'Percepção Passiva 10.', 0),
  ('assassino', 'Sentidos', 'Percepção Passiva 16.', 0),
  ('assassino', 'Evasion', 'If the assassin is subjected to an effect that allows it to make a Dexterity saving throw to take only half damage, the assassin instead takes no damage if it succeeds on the save and only half damage if it fails. It can’t use this trait if it has the Incapacitated condition.', 1),
  ('azer-piromante', 'Sentidos', 'Percepção Passiva 17.', 0),
  ('azer-piromante', 'Fire Aura', 'At the end of each of the azer’s turns, each creature of the azer’s choice in a 5-foot Emanation originating from the azer takes 11 (2d10) Fire damage unless the azer has the Incapacitated condition.', 1),
  ('azer-piromante', 'Illumination', 'The azer sheds Bright Light in a 10-foot radius and Dim Light for an additional 10 feet.', 2),
  ('azer-sentinela', 'Sentidos', 'Percepção Passiva 11.', 0),
  ('azer-sentinela', 'Fire Aura', 'At the end of each of the azer’s turns, each creature of the azer’s choice in a 5-foot Emanation originating from the azer takes 5 (1d10) Fire damage unless the azer has the Incapacitated condition.', 1),
  ('azer-sentinela', 'Illumination', 'The azer sheds Bright Light in a 10-foot radius and Dim Light for an additional 10 feet.', 2),
  ('balor', 'Sentidos', 'Visão Verdadeira 36 m. Percepção Passiva 19.', 0),
  ('balor', 'Death Throes', 'The balor explodes when it dies. Dexterity Saving Throw: DC 20, each creature in a 30-foot Emanation originating from the balor. Failure: 31 (9d6) Fire damage plus 31 (9d6) Force damage. Success: Half damage. Failure or Success: If the balor dies outside the Abyss, it gains a new body instantly, reviving with all its Hit Points somewhere in the Abyss.', 1),
  ('balor', 'Fire Aura', 'At the end of each of the balor’s turns, each creature in a 5-foot Emanation originating from the balor takes 13 (3d8) Fire damage.', 2),
  ('balor', 'Legendary Resistance (3/Day)', 'If the balor fails a saving throw, it can choose to succeed instead.', 3),
  ('balor', 'Magic Resistance', 'The balor has Advantage on saving throws against spells and other magical effects.', 4),
