  ('banshee', 'Detect Life', 'The banshee magically senses the direction of creatures up to 1 mile away that aren’t Constructs or Undead.', 1),
  ('banshee', 'Incorporeal Movement', 'The banshee can move through other creatures and objects as if they were Difficult Terrain. It takes 5 (1d10) Force damage if it ends its turn inside an object.', 2),
  ('barlgura', 'Sentidos', 'Visão às Cegas 9 m, Visão no Escuro 36 m. Percepção Passiva 15.', 0),
  ('barlgura', 'Demonic Restoration', 'If the barlgura dies outside the Abyss, its body dissolves into ichor, and it gains a new body instantly, reviving with all its Hit Points somewhere in the Abyss.', 1),
