  ('bola-de-aniquilacao', 'Sentidos', 'Visão às Cegas 36 m. Percepção Passiva 13.', 0),
  ('bola-de-aniquilacao', 'Astral Implosion', 'If the blob is reduced to 0 Hit Points, it implodes and ejects any creatures and objects engulfed by it into the Astral Sea. The blob itself vanishes, leaving behind a layer of slime on everything that was within 600 feet of it. In 1d20 years, the blob reconstitutes on a random world in the Material Plane.', 1),
  ('bola-de-aniquilacao', 'Legendary Resistance (4/Day)', 'If the blob fails a saving throw, it can choose to succeed instead.', 2),
  ('bola-de-aniquilacao', 'Magic Resistance', 'The blob has Advantage on saving throws against spells and other magical effects.', 3),
  ('bugbear-cacador', 'Sentidos', 'Visão no Escuro 18 m. Percepção Passiva 11.', 0),
  ('bugbear-cacador', 'Abduct', 'The bugbear needn’t spend extra movement to move a creature it is grappling.', 1),
  ('bugbear-guerreiro', 'Sentidos', 'Visão no Escuro 18 m. Percepção Passiva 10.', 0),
