  ('elemental-do-ar', 'Sentidos', 'Visão no Escuro 18 m. Percepção Passiva 10.', 0),
  ('elemental-do-ar', 'Air Form', 'The elemental can enter a creature’s space and stop there. It can move through a space as narrow as 1 inch without expending extra movement to do so.', 1),
  ('espada-voadora-animada', 'Sentidos', 'Visão às Cegas 18 m. Percepção Passiva 7.', 0),
  ('lorde-animal', 'Sentidos', 'Visão Verdadeira 36 m. Percepção Passiva 28.', 0),
  ('lorde-animal', 'Animal Lordship', 'An animal lord represents a Forager, Hunter, or Sage (DM’s choice), which determines certain traits in this stat block.', 1),
  ('lorde-animal', 'Legendary Resistance (4/Day)', 'If the animal lord fails a saving throw, it can choose to succeed instead.', 2),
  ('lorde-animal', 'Lordly Presence', 'Wisdom Saving Throw: DC 20, any enemy that starts its turn in a 30-foot Emanation originating from the animal lord. Failure: The target suffers one of the following effects:', 3),
  ('lorde-animal', 'Magic Resistance', 'The animal lord has Advantage on saving throws against spells and other magical effects.', 4),
  ('lorde-do-crime-bandido', 'Sentidos', 'Percepção Passiva 20.', 0),
  ('lorde-do-crime-bandido', 'Evasion', 'If the bandit is subjected to an effect that allows it to make a Dexterity saving throw to take only half damage, the bandit instead takes no damage if it succeeds on the save and only half damage if it fails. It can’t use this trait if it has the Incapacitated condition.', 1),
  ('naga-de-ossos', 'Sentidos', 'Visão no Escuro 18 m. Percepção Passiva 12.', 0),
  ('praga-de-agulha', 'Sentidos', 'Visão às Cegas 18 m. Percepção Passiva 9.', 0),
  ('praga-de-arvore', 'Sentidos', 'Visão às Cegas 18 m. Percepção Passiva 10.', 0),
  ('praga-de-galho', 'Sentidos', 'Visão às Cegas 18 m. Percepção Passiva 9.', 0),
  ('praga-de-galho', 'Pack Tactics', 'The blight has Advantage on an attack roll against a creature if at least one of the blight’s allies is within 5 feet of the creature and the ally doesn’t have the Incapacitated condition.', 1),
  ('praga-de-gulthias', 'Sentidos', 'Visão às Cegas 36 m. Percepção Passiva 19.', 0),
  ('praga-de-gulthias', 'Blight Seeds', 'When it finishes a Long Rest, the blight expels 1d6 seeds into unoccupied spaces on the ground within 30 feet of itself. After 24 hours, the seeds become creatures under the blight’s control. Roll 1d8 for each seed to determine the creature it becomes: on 1–4,Twig Blight; on 5–6, Needle Blight; on 7–8, Vine Blight.', 1),
  ('praga-de-videira', 'Sentidos', 'Visão às Cegas 18 m. Percepção Passiva 10.', 0),
  ('pudim-negro', 'Sentidos', 'Visão às Cegas 18 m. Percepção Passiva 8.', 0),
  ('pudim-negro', 'Amorphous', 'The pudding can move through a space as narrow as 1 inch without expending extra movement to do so.', 1),
  ('pudim-negro', 'Corrosive Form', 'A creature that hits the pudding with a melee attack roll takes 4 (1d8) Acid damage. Nonmagical ammunition is destroyed immediately after hitting the pudding and dealing any damage. Any nonmagical weapon takes a cumulative -1 penalty to attack rolls immediately after dealing damage to the pudding and coming into contact with it. The weapon is destroyed if the penalty reaches -5. The penalty can be removed by casting the Mending spell on the weapon.', 2),
  ('pudim-negro', 'Spider Climb', 'The pudding can climb difficult surfaces, including along ceilings, without needing to make an ability check.', 3),
  ('tapete-sufocante-animado', 'Sentidos', 'Visão às Cegas 18 m. Percepção Passiva 6.', 0),
  ('vassoura-animada', 'Sentidos', 'Visão às Cegas 18 m. Percepção Passiva 7.', 0),
  ('vassoura-animada', 'Flyby', 'The broom doesn’t provoke an Opportunity Attack when it flies out of an enemy’s reach.', 1);

