INSERT INTO rpg.phb_creature_template_action (
  template_slug, name, action_bucket, attack_bonus, damage_expression, description, sort_order
) VALUES
  ('aarakocra-aeromante', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The aarakocra makes two Wind Staff attacks, and it can use Spellcasting to cast Gust of Wind.', 1),
  ('aarakocra-aeromante', 'Wind Staff', 'action'::rpg.actor_action_bucket, 5, '7', 'Melee or Ranged Attack Roll: +5, reach 5 ft. or range 120 ft. Hit: 7 (1d8 + 3) Bludgeoning damage plus 11 (2d10) Lightning damage.', 2),
  ('aarakocra-aeromante', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The aarakocra casts one of the following spells, requiring no Material components and using Wisdom as the spellcasting ability (spell save DC 13):', 3),
  ('aarakocra-aeromante', 'Feather Fall (1/Day)', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'The aarakocra casts Feather Fall in response to that spell’s trigger, using the same spellcasting ability as Spellcasting.', 4),
  ('aarakocra-escaramucador', 'Talons', 'action'::rpg.actor_action_bucket, 4, '4', 'Melee Attack Roll: +4, reach 5 ft. Hit: 4 (1d4 + 2) Slashing damage, or 9 (3d4 + 2) Slashing damage if the aarakocra moved 30+ feet straight toward the target immediately before the hit.', 1),
  ('aarakocra-escaramucador', 'Wind Javelin', 'action'::rpg.actor_action_bucket, 4, '5', 'Melee or Ranged Attack Roll: +4, reach 5 ft. or range 30/120 ft. Hit: 5 (1d6 + 2) Piercing damage plus 2 (1d4) Thunder damage. Hit or Miss: The javelin magically returns to the aarakocra’s hand immediately after a ranged attack.', 2),
  ('abolete', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The aboleth makes two Tentacle attacks and uses either Consume Memories or Dominate Mind if available.', 1),
  ('abolete', 'Tentacle', 'action'::rpg.actor_action_bucket, 9, '12', 'Melee Attack Roll: +9, reach 15 ft. Hit: 12 (2d6 + 5) Bludgeoning damage. If the target is a Large or smaller creature, it has the Grappled condition (escape DC 14) from one of four tentacles.', 2),
  ('abolete', 'Consume Memories', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Intelligence Saving Throw: DC 16, one creature within 30 feet that is Charmed or Grappled by the aboleth. Failure: 10 (3d6) Psychic damage. Success: Half damage. Failure or Success: The aboleth gains the target’s memories if the target is a Humanoid and is reduced to 0 Hit Points by this action.', 3),
  ('abolete', 'Dominate Mind (2/Day)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Wisdom Saving Throw: DC 16, one creature the aboleth can see within 30 feet. Failure: The target has the Charmed condition until the aboleth dies or is on a different plane of existence from the target. While Charmed, the target acts as an ally to the aboleth and is under its control while within 60 feet of it. In addition, the aboleth and the target can communicate telepathically with each other over any distance.', 4),
  ('abolete', 'Legendary Action Uses', 'legendary'::rpg.actor_action_bucket, NULL, NULL, '3 (4 in Lair). Immediately after another creature''s turn, the aboleth can expend a use to take one of the following actions. The aboleth regains all expended uses at the start of each of its turns.', 5),
  ('abolete', 'Lash', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The aboleth makes one Tentacle attack.', 6),
  ('abolete', 'Psychic Drain', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'If the aboleth has at least one creature Charmed or Grappled, it uses Consume Memories and regains 5 (1d10) Hit Points.', 7),
  ('ankheg', 'Bite', 'action'::rpg.actor_action_bucket, 5, '10', 'Melee Attack Roll: +5 (with Advantage if the target is Grappled by the ankheg), reach 5 ft. Hit: 10 (2d6 + 3) Slashing damage plus 3 (1d6) Acid damage. If the target is a Large or smaller creature, it has the Grappled condition (escape DC 13).', 1),
  ('ankheg', 'Acid Spray (Recharge 6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 12, each creature in a 30-foot-long, 5-foot-wide Line. Failure: 14 (4d6) Acid damage. Success: Half damage.', 2),
  ('arbusto-despertado', 'Rake', 'action'::rpg.actor_action_bucket, 1, '1', 'Melee Attack Roll: +1, reach 5 ft. Hit: 1 Slashing damage.', 1),
  ('arcanalote', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The arcanaloth makes three Fiendish Burst attacks. It can replace one attack with a Banishing Claw attack.', 1),
  ('arcanalote', 'Banishing Claw (Requires Soul Tome)', 'action'::rpg.actor_action_bucket, 9, '10', 'Melee Attack Roll: +9, reach 5 ft. Hit: 10 (2d4 + 5) Slashing damage plus 19 (3d12) Psychic damage. If the target is a creature, it is subjected to the following effect. Charisma Saving Throw: DC 17. Failure: The target is trapped in a demiplane inside the Soul Tome. While trapped there, the target has the Incapacitated condition. At the end of each of its turns, the target repeats the save, escaping the tome on a success. When the target escapes, it appears in the space it left or, if that space is occupied, the nearest unoccupied space.', 2),
  ('arcanalote', 'Fiendish Burst', 'action'::rpg.actor_action_bucket, 9, '31', 'Melee or Ranged Attack Roll: +9, reach 5 ft. or range 120 ft. Hit: 31 (4d12 + 5) Necrotic damage.', 3),
  ('arcanalote', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The arcanaloth casts one of the following spells, requiring no Material components and using Intelligence as the spellcasting ability (spell save DC 17):', 4),
  ('arcanalote', 'Teleport', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The arcanaloth teleports up to 30 feet to an unoccupied space it can see.', 5),
  ('arcanalote', 'Counterspell', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'The arcanaloth casts Counterspell in response to that spell’s trigger, using the same spellcasting ability as Spellcasting.', 6),
  ('armadura-animada', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The armor makes two Slam attacks.', 1),
  ('armadura-animada', 'Slam', 'action'::rpg.actor_action_bucket, 4, '5', 'Melee Attack Roll: +4, reach 5 ft. Hit: 5 (1d6 + 2) Bludgeoning damage.', 2),
  ('arquibruxa', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The hag makes two Spectral Claw attacks and uses Crackling Wave.', 1),
  ('arquibruxa', 'Spectral Claw', 'action'::rpg.actor_action_bucket, 14, '17', 'Melee or Ranged Attack Roll: +14, reach 10 ft. or range 60 ft. Hit: 17 (3d6 + 7) Force damage. If the target is a Large or smaller creature, it has the Prone condition.', 2),
  ('arquibruxa', 'Crackling Wave', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 22, each creature in a 60-foot Cone. Failure: 32 (5d12) Lightning damage. Success: Half damage. Failure or Success: The target is cursed until the end of the hag’s next turn. The target can’t take Reactions until the curse ends.', 3),
  ('arquibruxa', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The hag casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 22):', 4),
  ('arquibruxa', 'Witch Strike', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'Each creature cursed by the hag and within 60 feet of it takes 14 (4d6) Lightning damage.', 5),
  ('arquibruxa', 'Tongue Twister', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'The hag casts Counterspell in response to that spell’s trigger, using the same spellcasting ability as Spellcasting. If the target fails its saving throw, it is cursed until the end of its next turn. Until the curse ends, the target can’t cast spells with a Verbal component, and when it speaks, it says the opposite of what it means.', 6),
  ('arquibruxa', 'Legendary Action Uses', 'legendary'::rpg.actor_action_bucket, NULL, NULL, '3 (4 in Lair). Immediately after another creature''s turn, the arch-hag can expend a use to take one of the following actions. The arch-hag regains all expended uses at the start of each of its turns.', 7),
  ('arquibruxa', 'Hag’s Swipe', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The hag makes one Spectral Claw attack.', 8),
  ('arquibruxa', 'Malicious Magic', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The hag uses Spellcasting to cast Dimension Door or Hypnotic Pattern. The hag can’t take this action again until the start of its next turn.', 9),
  ('arvore-despertada', 'Slam', 'action'::rpg.actor_action_bucket, 6, '14', 'Melee Attack Roll: +6, reach 10 ft. Hit: 14 (3d6 + 4) Bludgeoning damage.', 1),
  ('assassino', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The assassin makes three attacks, using Shortsword or Light Crossbow in any combination.', 1),
  ('assassino', 'Shortsword', 'action'::rpg.actor_action_bucket, 7, '7', 'Melee Attack Roll: +7, reach 5 ft. Hit: 7 (1d6 + 4) Piercing damage plus 17 (5d6) Poison damage, and the target has the Poisoned condition until the start of the assassin’s next turn.', 2),
  ('assassino', 'Light Crossbow', 'action'::rpg.actor_action_bucket, 7, '8', 'Ranged Attack Roll: +7, range 80/320 ft. Hit: 8 (1d8 + 4) Piercing damage plus 21 (6d6) Poison damage.', 3),
  ('assassino', 'Cunning Action', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The assassin takes the Dash, Disengage, or Hide action.', 4),
  ('azer-piromante', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The azer makes two Flame Burst attacks.', 1),
  ('azer-piromante', 'Flame Burst', 'action'::rpg.actor_action_bucket, 7, '15', 'Melee or Ranged Attack Roll: +7, reach 5 ft. or range 120 ft. Hit: 15 (2d10 + 4) Fire damage.', 2),
  ('azer-piromante', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The azer casts one of the following spells, requiring no Material components and using Wisdom as the spellcasting ability (spell save DC 15):', 3),
  ('azer-piromante', 'Hellish Rebuke (2/Day)', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'The azer casts Hellish Rebuke in response to that spell’s trigger, using the same spellcasting ability as Spellcasting.', 4),
  ('azer-sentinela', 'Burning Hammer', 'action'::rpg.actor_action_bucket, 5, '8', 'Melee Attack Roll: +5, reach 5 ft. Hit: 8 (1d10 + 3) Bludgeoning damage plus 3 (1d6) Fire damage.', 1),
  ('azer-sentinela', 'Beckon Air', 'action'::rpg.actor_action_bucket, NULL, NULL, 'You create a breeze strong enough to ripple cloth, stir dust, rustle leaves, and close open doors and shutters, all in a 5-foot Cube. Doors and shutters being held open by someone or something aren’t affected.', 2),
  ('azer-sentinela', 'Beckon Earth', 'action'::rpg.actor_action_bucket, NULL, NULL, 'You create a thin shroud of dust or sand that covers surfaces in a 5-foot-square area, or you cause a single word to appear in your handwriting in a patch of dirt or sand.', 3),
  ('azer-sentinela', 'Beckon Fire', 'action'::rpg.actor_action_bucket, NULL, NULL, 'You create a thin cloud of harmless embers and colored, scented smoke in a 5-foot Cube. You choose the color and scent, and the embers can light candles, torches, or lamps in that area. The smoke’s scent lingers for 1 minute.', 4),
  ('azer-sentinela', 'Beckon Water', 'action'::rpg.actor_action_bucket, NULL, NULL, 'You create a spray of cool mist that lightly dampens creatures and objects in a 5-foot Cube. Alternatively, you create 1 cup of clean water either in an open container or on a surface, and the water evaporates in 1 minute.', 5),
  ('azer-sentinela', 'Sculpt Element', 'action'::rpg.actor_action_bucket, NULL, NULL, 'You cause dirt, sand, fire, smoke, mist, or water that can fit in a 1-foot Cube to assume a crude shape (such as that of a creature) for 1 hour.', 6),
  ('balor', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The balor makes one Flame Whip attack and one Lightning Blade attack.', 1),
  ('balor', 'Flame Whip', 'action'::rpg.actor_action_bucket, 14, '18', 'Melee Attack Roll: +14, reach 30 ft. Hit: 18 (3d6 + 8) Force damage plus 17 (5d6) Fire damage. If the target is a Huge or smaller creature, the balor pulls the target up to 25 feet straight toward itself, and the target has the Prone condition.', 2),
  ('balor', 'Lightning Blade', 'action'::rpg.actor_action_bucket, 14, '21', 'Melee Attack Roll: +14, reach 10 ft. Hit: 21 (3d8 + 8) Force damage plus 22 (4d10) Lightning damage, and the target can’t take Reactions until the start of the balor’s next turn.', 3),
  ('balor', 'Teleport', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The balor teleports itself or a willing demon within 10 feet of itself up to 60 feet to an unoccupied space the balor can see.', 4),
  ('bandido', 'Scimitar', 'action'::rpg.actor_action_bucket, 3, '4', 'Melee Attack Roll: +3, reach 5 ft. Hit: 4 (1d6 + 1) Slashing damage.', 1),
  ('bandido', 'Light Crossbow', 'action'::rpg.actor_action_bucket, 3, '5', 'Ranged Attack Roll: +3, range 80/320 ft. Hit: 5 (1d8 + 1) Piercing damage.', 2),
  ('bandido-enganador', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The bandit makes three Dagger attacks.', 1),
  ('bandido-enganador', 'Dagger', 'action'::rpg.actor_action_bucket, 6, '8', 'Melee or Ranged Attack Roll: +6, reach 5 ft. or range 20/60 ft. Hit: 8 (2d4 + 3) Piercing damage plus 10 (3d6) Poison damage.', 2),
  ('bandido-enganador', 'Blinding Flash (Recharge 4–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 14, each creature in a 10-foot-radius Sphere centered on a point the bandit can see within 120 feet. Failure: 13 (3d6 + 3) Radiant damage, and the target has the Blinded condition until the start of the bandit’s next turn. Success: Half damage only.', 3),
  ('bandido-enganador', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The bandit casts one of the following spells, using Intelligence as the spellcasting ability (spell save DC 14):', 4),
  ('banshee', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The banshee makes two Corrupting Touch attacks and uses Horrify.', 1),
  ('banshee', 'Corrupting Touch', 'action'::rpg.actor_action_bucket, 5, '7', 'Melee Attack Roll: +5, reach 5 ft. Hit: 7 (1d8 + 3) Necrotic damage.', 2),
  ('banshee', 'Horrify', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Wisdom Saving Throw: DC 13, one creature the banshee can see within 60 feet that can see the banshee. Failure: The target has the Frightened condition until the start of the banshee’s next turn. Success: The target is immune to this banshee’s Horrify for 24 hours.', 3),
  ('banshee', 'Deathly Wail (1/Day)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The banshee releases a mournful wail if it isn’t in sunlight. Constitution Saving Throw: DC 13, each creature within 30 feet that can hear the wail and isn’t a Construct or an Undead. Failure: If the target has 25 Hit Points or fewer, it drops to 0 Hit Points. Otherwise, the target takes 10 (3d6) Psychic damage.', 4),
  ('barlgura', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The barlgura makes one Tormenting Bite attack and two Thrash attacks.', 1),
  ('barlgura', 'Tormenting Bite', 'action'::rpg.actor_action_bucket, 7, '11', 'Melee Attack Roll: +7, reach 5 ft. Hit: 11 (2d6 + 4) Piercing damage plus 13 (2d12) Psychic damage.', 2),
  ('barlgura', 'Thrash', 'action'::rpg.actor_action_bucket, 7, '9', 'Melee Attack Roll: +7, reach 5 ft. Hit: 9 (1d10 + 4) Bludgeoning damage. If the target is a Large or smaller creature, it has the Prone condition.', 3),
  ('barlgura', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The barlgura casts one of the following spells, requiring no Material components and using Wisdom as the spellcasting ability (spell save DC 13):', 4),
  ('barlgura', 'Leap', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The barlgura jumps up to 40 feet by spending 10 feet of movement.', 5),
  ('basilisco', 'Bite', 'action'::rpg.actor_action_bucket, 5, '10', 'Melee Attack Roll: +5, reach 5 ft. Hit: 10 (2d6 + 3) Piercing damage plus 7 (2d6) Poison damage.', 1),
  ('basilisco', 'Petrifying Gaze (Recharge 4–6)', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 12, each creature in a 30-foot Cone. If the basilisk sees its reflection in the Cone, the basilisk must make this save. First Failure: The target has the Restrained condition and repeats the save at the end of its next turn if it is still Restrained, ending the effect on itself on a success. Second Failure: The target has the Petrified condition instead of the Restrained condition.', 2),
  ('behir', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The behir makes one Bite attack and uses Constrict.', 1),
  ('behir', 'Bite', 'action'::rpg.actor_action_bucket, 10, '19', 'Melee Attack Roll: +10, reach 10 ft. Hit: 19 (2d12 + 6) Piercing damage plus 11 (2d10) Lightning damage.', 2),
  ('behir', 'Constrict', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Strength Saving Throw: DC 18, one Large or smaller creature the behir can see within 5 feet. Failure: 28 (5d8 + 6) Bludgeoning damage. The target has the Grappled condition (escape DC 16), and it has the Restrained condition until the grapple ends.', 3),
  ('behir', 'Lightning Breath (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 16, each creature in a 90-foot-long, 5-foot-wide Line. Failure: 66 (12d10) Lightning damage. Success: Half damage.', 4),
  ('behir', 'Swallow', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 18, one Large or smaller creature Grappled by the behir (the behir can have only one creature swallowed at a time). Failure: The behir swallows the target, which is no longer Grappled. While swallowed, a creature has the Blinded and Restrained conditions, has Total Cover against attacks and other effects outside the behir, and takes 21 (6d6) Acid damage at the start of each of the behir’s turns.', 5),
  ('beholder', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The beholder uses Eye Rays three times.', 1),
  ('beholder', 'Bite', 'action'::rpg.actor_action_bucket, 8, '13', 'Melee Attack Roll: +8, reach 5 ft. Hit: 13 (3d6 + 3) Piercing damage.', 2),
  ('beholder', 'Eye Rays', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The beholder randomly shoots one of the following magical rays at a target it can see within 120 feet of itself (roll 1d10; reroll if the beholder has already used that ray during this turn):', 3),
  ('beholder', 'Antimagic Cone', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The beholder’s central eye emits an antimagic wave in a 150-foot Cone. Until the start of the beholder’s next turn, that area acts as an Antimagic Field spell, and that area works against the beholder’s own Eye Rays.', 4),
  ('beholder', 'Legendary Action Uses', 'legendary'::rpg.actor_action_bucket, NULL, NULL, '3 (4 in Lair). Immediately after another creature''s turn, the beholder can expend a use to take one of the following actions. The beholder regains all expended uses at the start of each of its turns.', 5),
  ('beholder', 'Chomp', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The beholder makes two Bite attacks.', 6),
  ('beholder', 'Glare', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The beholder uses Eye Rays.', 7),
  ('berserker', 'Greataxe', 'action'::rpg.actor_action_bucket, 5, '9', 'Melee Attack Roll: +5, reach 5 ft. Hit: 9 (1d12 + 3) Slashing damage.', 1),
  ('berserker-comandante', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The berserker makes three attacks, using Greataxe or Javelin in any combination.', 1),
  ('berserker-comandante', 'Greataxe', 'action'::rpg.actor_action_bucket, 7, '10', 'Melee Attack Roll: +7, reach 5 ft. Hit: 10 (1d12 + 4) Slashing damage, plus 10 (3d6) Thunder damage to the target or another creature within 5 feet of the target.', 2),
  ('berserker-comandante', 'Javelin', 'action'::rpg.actor_action_bucket, 7, '18', 'Melee or Ranged Attack Roll: +7, reach 5 ft. or range 30/120 ft. Hit: 18 (4d6 + 4) Piercing damage, and the target’s Speed decreases by 5 feet until the start of the berserker’s next turn.', 3),
  ('berserker-comandante', 'Frenzied Rush', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'Each ally within 30 feet of the berserker can take a Reaction to move up to half the ally’s Speed without provoking Opportunity Attacks. The berserker can also move up to half its Speed without provoking Opportunity Attacks.', 4),
  ('bico-de-machado', 'Beak', 'action'::rpg.actor_action_bucket, 4, '6', 'Melee Attack Roll: +4, reach 5 ft. Hit: 6 (1d8 + 2) Slashing damage.', 1),
  ('bico-de-machado-gigante', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The axe beak makes one Sharpened Beak attack and one Talons attack.', 1),
  ('bico-de-machado-gigante', 'Sharpened Beak', 'action'::rpg.actor_action_bucket, 8, '18', 'Melee Attack Roll: +8, reach 10 ft. Hit: 18 (2d12 + 5) Slashing damage, and a creature within 5 feet of the target (axe beak’s choice) takes 6 (1d12) Slashing damage.', 2),
  ('bico-de-machado-gigante', 'Talons', 'action'::rpg.actor_action_bucket, 8, '14', 'Melee Attack Roll: +8, reach 5 ft. Hit: 14 (2d8 + 5) Piercing damage. If the target is a Large or smaller creature, it has the Prone condition.', 3),
  ('bola-de-aniquilacao', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The blob makes two Pseudopod attacks and uses Engulf. It can replace one attack with a use of Restraining Glob.', 1),
  ('bola-de-aniquilacao', 'Pseudopod', 'action'::rpg.actor_action_bucket, 15, '24', 'Melee Attack Roll: +15, reach 30 ft. Hit: 24 (3d10 + 8) Force damage.', 2),
  ('bola-de-aniquilacao', 'Engulf', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The blob moves up to its Speed and can move through the spaces of Huge or smaller creatures and objects. Strength Saving Throw: DC 23, each creature or object whose space the blob enters for the first time during this move. Failure: The target is engulfed. While engulfed, a target has Total Cover against attacks and other effects outside the blob, and when the blob moves, the engulfed target moves with it. A nonmagical object is destroyed after spending 1 minute engulfed.', 3),
  ('bola-de-aniquilacao', 'Restraining Glob', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The blob lobs a slimy glob at one Large or smaller creature it can see within 600 feet of itself. Dexterity Saving Throw: DC 23, the targeted creature. Failure: 18 (3d6 + 8) Acid damage. The glob rolls the target 60 feet straight toward the blob, and the target has the Restrained condition until the end of its next turn, when the glob harmlessly dissolves. Success: Half damage only.', 4),
  ('bola-de-aniquilacao', 'Legendary Action Uses', 'legendary'::rpg.actor_action_bucket, NULL, NULL, '3. Immediately after another creature''s turn, the blob can expend a use to take one of the following actions. The blob regains all expended uses at the start of each of its turns.', 5),
  ('bola-de-aniquilacao', 'Decay', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The blob deals 14 (4d6) Necrotic damage to each creature engulfed by it. The blob can’t take this action again until the start of its next turn.', 6),
  ('bola-de-aniquilacao', 'Grasping Glob', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The blob uses Restraining Glob. The blob can’t take this action again until the start of its next turn.', 7),
  ('bola-de-aniquilacao', 'Lashing Goop', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The blob makes one Pseudopod attack.', 8),
  ('bugbear-cacador', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The bugbear makes two Javelin or Morningstar attacks.', 1),
  ('bugbear-cacador', 'Javelin', 'action'::rpg.actor_action_bucket, 5, '13', 'Melee or Ranged Attack Roll: +5, reach 10 ft. or range 30/120 ft. Hit: 13 (3d6 + 3) Piercing damage.', 2),
  ('bugbear-cacador', 'Morningstar', 'action'::rpg.actor_action_bucket, 5, '12', 'Melee Attack Roll: +5 (with Advantage if the target is Grappled by the bugbear), reach 10 ft. Hit: 12 (2d8 + 3) Piercing damage.', 3),
  ('bugbear-cacador', 'Quick Grapple', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 13, one Medium or smaller creature the bugbear can see within 10 feet. Failure: The target has the Grappled condition (escape DC 13).', 4),
  ('bugbear-guerreiro', 'Grab', 'action'::rpg.actor_action_bucket, 4, '9', 'Melee Attack Roll: +4, reach 10 ft. Hit: 9 (2d6 + 2) Bludgeoning damage. If the target is a Medium or smaller creature, it has the Grappled condition (escape DC 12).', 1),
  ('bugbear-guerreiro', 'Light Hammer', 'action'::rpg.actor_action_bucket, 4, '9', 'Melee or Ranged Attack Roll: +4 (with Advantage if the target is Grappled by the bugbear), reach 10 ft. or range 20/60 ft. Hit: 9 (3d4 + 2) Bludgeoning damage.', 2),
  ('bulette', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The bulette makes two Bite attacks.', 1),
  ('bulette', 'Bite', 'action'::rpg.actor_action_bucket, 7, '17', 'Melee Attack Roll: +7, reach 5 ft. Hit: 17 (2d12 + 4) Piercing damage.', 2),
  ('bulette', 'Deadly Leap', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The bulette spends 5 feet of movement to jump to a space within 15 feet that contains one or more Large or smaller creatures. Dexterity Saving Throw: DC 15, each creature in the bulette’s destination space. Failure: 19 (3d12) Bludgeoning damage, and the target has the Prone condition. Success: Half damage, and the target is pushed 5 feet straight away from the bulette.', 3),
  ('bulette', 'Leap', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The bulette jumps up to 30 feet by spending 10 feet of movement.', 4),
  ('bulette-filhote', 'Bite', 'action'::rpg.actor_action_bucket, 5, '14', 'Melee Attack Roll: +5, reach 5 ft. Hit: 14 (2d10 + 3) Piercing damage.', 1),
  ('bulette-filhote', 'Leap', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The bulette jumps up to 30 feet by spending 10 feet of movement.', 2),
  ('bullywug-guerreiro', 'Insectile Rapier', 'action'::rpg.actor_action_bucket, 4, '6', 'Melee Attack Roll: +4, reach 5 ft. Hit: 6 (1d8 + 2) Piercing damage plus 2 (1d4) Poison damage.', 1),
  ('bullywug-guerreiro', 'Leap', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The bullywug jumps up to 30 feet by spending 10 feet of movement.', 2),
  ('bullywug-sabio-do-pantano', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The bullywug makes two Bog Staff attacks. It can replace any attack with a use of Spellcasting to cast Ray of Sickness.', 1),
  ('bullywug-sabio-do-pantano', 'Bog Staff', 'action'::rpg.actor_action_bucket, 5, '7', 'Melee Attack Roll: +5, reach 5 ft. Hit: 7 (1d8 + 3) Bludgeoning damage plus 10 (3d6) Poison damage.', 2),
  ('bullywug-sabio-do-pantano', 'Spellcasting', 'action'::rpg.actor_action_bucket, 5, NULL, 'The bullywug casts one of the following spells, using Wisdom as the spellcasting ability (spell save DC 13, +5 to hit with spell attacks):', 3),
  ('bullywug-sabio-do-pantano', 'Leap', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The bullywug jumps up to 30 feet by spending 10 feet of movement.', 4),
  ('cao-piscante', 'Bite', 'action'::rpg.actor_action_bucket, 5, '5', 'Melee Attack Roll: +5, reach 5 ft. Hit: 5 (1d4 + 3) Piercing damage.', 1),
  ('cao-piscante', 'Teleport (Recharge 4–6)', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The dog teleports up to 40 feet to an unoccupied space it can see.', 2),
  ('capitao-bandido', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The bandit makes two attacks, using Scimitar and Pistol in any combination.', 1),
  ('capitao-bandido', 'Scimitar', 'action'::rpg.actor_action_bucket, 5, '6', 'Melee Attack Roll: +5, reach 5 ft. Hit: 6 (1d6 + 3) Slashing damage.', 2),
  ('capitao-bandido', 'Pistol', 'action'::rpg.actor_action_bucket, 5, '8', 'Ranged Attack Roll: +5, range 30/90 ft. Hit: 8 (1d10 + 3) Piercing damage.', 3),
  ('capitao-bandido', 'Parry', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'Trigger: The bandit is hit by a melee attack roll while holding a weapon. Response: The bandit adds 2 to its AC against that attack, possibly causing it to miss.', 4),
  ('diabo-barbudo', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The devil makes one Beard attack and one Infernal Glaive attack.', 1),
  ('diabo-barbudo', 'Beard', 'action'::rpg.actor_action_bucket, 5, '7', 'Melee Attack Roll: +5, reach 5 ft. Hit: 7 (1d8 + 3) Piercing damage, and the target has the Poisoned condition until the start of the devil’s next turn. Until this poison ends, the target can’t regain Hit Points.', 2),
  ('diabo-barbudo', 'Infernal Glaive', 'action'::rpg.actor_action_bucket, 5, '8', 'Melee Attack Roll: +5, reach 10 ft. Hit: 8 (1d10 + 3) Slashing damage. If the target is a creature and doesn’t already have an infernal wound, it is subjected to the following effect. Constitution Saving Throw: DC 12. Failure: The target receives an infernal wound. While wounded, the target loses 5 (1d10) Hit Points at the start of each of its turns. The wound closes after 1 minute, after a spell restores Hit Points to the target, or after the target or a creature within 5 feet of it takes an action to stanch the wound, doing so by succeeding on a DC 12 Wisdom (Medicine) check.', 3),
  ('diabo-de-ossos', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The devil makes two Claw attacks and one Infernal Sting attack.', 1),
  ('diabo-de-ossos', 'Claw', 'action'::rpg.actor_action_bucket, 8, '13', 'Melee Attack Roll: +8, reach 10 ft. Hit: 13 (2d8 + 4) Slashing damage.', 2),
  ('diabo-de-ossos', 'Infernal Sting', 'action'::rpg.actor_action_bucket, 8, '15', 'Melee Attack Roll: +8, reach 10 ft. Hit: 15 (2d10 + 4) Piercing damage plus 18 (4d8) Poison damage, and the target has the Poisoned condition until the start of the devil’s next turn. While Poisoned, the target can’t regain Hit Points.', 3),
  ('diabo-espinhoso', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The devil makes one Claws attack and one Tail attack, or it makes two Hurl Flame attacks.', 1),
  ('diabo-espinhoso', 'Claws', 'action'::rpg.actor_action_bucket, 6, '10', 'Melee Attack Roll: +6, reach 5 ft. Hit: 10 (2d6 + 3) Piercing damage. If the target is a Large or smaller creature, it has the Grappled condition (escape DC 13) from both claws.', 2),
  ('diabo-espinhoso', 'Tail', 'action'::rpg.actor_action_bucket, 6, '14', 'Melee Attack Roll: +6, reach 10 ft. Hit: 14 (2d10 + 3) Slashing damage.', 3),
  ('diabo-espinhoso', 'Hurl Flame', 'action'::rpg.actor_action_bucket, 5, '17', 'Ranged Attack Roll: +5, range 150 ft. Hit: 17 (5d6) Fire damage. If the target is a flammable object that isn’t being worn or carried, it starts burning.', 4),
  ('dragao-azul-adulto', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The dragon makes three Rend attacks. It can replace one attack with a use of Spellcasting to cast Shatter.', 1),
  ('dragao-azul-adulto', 'Rend', 'action'::rpg.actor_action_bucket, 12, '16', 'Melee Attack Roll: +12, reach 10 ft. Hit: 16 (2d8 + 7) Slashing damage plus 5 (1d10) Lightning damage.', 2),
  ('dragao-azul-adulto', 'Lightning Breath (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 19, each creature in a 90-foot-long, 5-foot-wide Line. Failure: 60 (11d10) Lightning damage. Success: Half damage.', 3),
  ('dragao-azul-adulto', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The dragon casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 18):', 4),
  ('dragao-azul-adulto', 'Legendary Action Uses', 'legendary'::rpg.actor_action_bucket, NULL, NULL, '3 (4 in Lair). Immediately after another creature''s turn, the dragon can expend a use to take one of the following actions. The dragon regains all expended uses at the start of each of its turns.', 5),
  ('dragao-azul-adulto', 'Cloaked Flight', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The dragon uses Spellcasting to cast Invisibility on itself, and it can fly up to half its Fly Speed. The dragon can’t take this action again until the start of its next turn.', 6),
  ('dragao-azul-adulto', 'Sonic Boom', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The dragon uses Spellcasting to cast Shatter. The dragon can’t take this action again until the start of its next turn.', 7),
  ('dragao-azul-adulto', 'Tail Swipe', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The dragon makes one Rend attack.', 8),
  ('dragao-azul-anciano', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The dragon makes three Rend attacks. It can replace one attack with a use of Spellcasting to cast Shatter (level 3 version).', 1),
