  ('naga-de-ossos', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The naga casts one of the following spells, requiring no Material components and using Intelligence as the spellcasting ability (spell save DC 13):', 4),
  ('praga-de-agulha', 'Claw', 'action'::rpg.actor_action_bucket, 3, '6', 'Melee Attack Roll: +3, reach 5 ft. Hit: 6 (2d4 + 1) Slashing damage.', 1),
  ('praga-de-agulha', 'Needles', 'action'::rpg.actor_action_bucket, 3, '6', 'Ranged Attack Roll: +3, range 30/60 ft. Hit: 6 (2d4 + 1) Piercing damage.', 2),
  ('praga-de-arvore', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The blight makes two Branch attacks and uses Grasping Root.', 1),
  ('praga-de-arvore', 'Branch', 'action'::rpg.actor_action_bucket, 9, '16', 'Melee Attack Roll: +9, reach 15 ft. Hit: 16 (3d6 + 6) Bludgeoning damage.', 2),
  ('praga-de-arvore', 'Grasping Root', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Strength Saving Throw: DC 17, one Large or smaller creature the blight can see within 15 feet. Failure: The target is pulled up to 10 feet straight toward the blight and has the Grappled condition (escape DC 16) from one of six roots. Until the grapple ends, the target takes 13 (2d6 + 6) Bludgeoning damage at the start of each of its turns.', 3),
  ('praga-de-arvore', 'Gnash', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 17, one creature Grappled by the blight. Failure: 19 (3d8 + 6) Piercing damage. Success: Half damage.', 4),
  ('praga-de-galho', 'Claw', 'action'::rpg.actor_action_bucket, 4, '4', 'Melee Attack Roll: +4, reach 5 ft. Hit: 4 (1d4 + 2) Slashing damage.', 1),
  ('praga-de-gulthias', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The blight makes two attacks, using Slam or Thorn Volley in any combination. It also uses Life-Draining Root.', 1),
  ('praga-de-gulthias', 'Slam', 'action'::rpg.actor_action_bucket, 12, '25', 'Melee Attack Roll: +12, reach 10 ft. Hit: 25 (4d8 + 7) Bludgeoning damage.', 2),
  ('praga-de-gulthias', 'Thorn Volley', 'action'::rpg.actor_action_bucket, 12, '20', 'Ranged Attack Roll: +12, range 60/180 ft. Hit: 20 (3d8 + 7) Piercing damage.', 3),
  ('praga-de-gulthias', 'Life-Draining Root', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 20, one Huge or smaller creature the blight can see within 30 feet. Failure: 14 (2d6 + 7) Necrotic damage, and the target has the Grappled condition (escape DC 17) from one of six roots. Until the grapple ends, the target has the Restrained condition and takes 14 (4d6) Necrotic damage at the start of each of its turns. The target’s Hit Point maximum decreases by an amount equal to the Necrotic damage taken, and the blight regains Hit Points equal to that amount.', 4),
  ('praga-de-videira', 'Constricting Vine', 'action'::rpg.actor_action_bucket, 4, '6', 'Melee Attack Roll: +4, reach 10 ft. Hit: 6 (1d8 + 2) Bludgeoning damage. If the target is a Large or smaller creature, it has the Grappled condition (escape DC 12). Until the grapple ends, the target takes 4 (1d8) Bludgeoning damage at the start of each of its turns, and the blight can’t make Constricting Vine attacks.', 1),
  ('praga-de-videira', 'Entangling Plants (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The blight casts the Entangle spell, using Constitution as the spellcasting ability (spell save DC 12).', 2),
  ('pudim-negro', 'Dissolving Pseudopod', 'action'::rpg.actor_action_bucket, 5, '17', 'Melee Attack Roll: +5, reach 10 ft. Hit: 17 (4d6 + 3) Acid damage. Nonmagical armor worn by the target takes a -1 penalty to the AC it offers. The armor is destroyed if the penalty reduces its AC to 10. The penalty can be removed by casting the Mending spell on the armor.', 1),
  ('pudim-negro', 'Split', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'Trigger: While the pudding is Large or Medium and has 10+ Hit Points, it becomes Bloodied or is subjected to Lightning or Slashing damage. Response: The pudding splits into two new Black Puddings. Each new pudding is one size smaller than the original pudding and acts on its Initiative. The original pudding’s Hit Points are divided evenly between the new puddings (round down).', 2),
  ('tapete-sufocante-animado', 'Smother', 'action'::rpg.actor_action_bucket, 5, '10', 'Melee Attack Roll: +5, reach 5 ft. Hit: 10 (2d6 + 3) Bludgeoning damage. If the target is a Medium or smaller creature, the rug can give it the Grappled condition (escape DC 13) instead of dealing damage. Until the grapple ends, the target has the Blinded and Restrained conditions, is suffocating, and takes 10 (2d6 + 3) Bludgeoning damage at the start of each of its turns. The rug can smother only one creature at a time.', 1),
  ('vassoura-animada', 'Slam', 'action'::rpg.actor_action_bucket, 5, '5', 'Melee Attack Roll: +5, reach 5 ft. Hit: 5 (1d4 + 3) Bludgeoning damage.', 1);

